BATCHES = {
 "B01": ["AS-001","AS-002","AS-003","AS-004","AS-005","AS-007","AS-008","AS-009","AS-010","AS-011","AS-012","AS-013","AS-014","AS-015","AS-204","AS-205","AS-206","AS-207","AS-208","AS-209"],
 "B02": ["AS-210","AS-211","AS-212","AS-213","AS-215","AS-301","AS-302","AS-303","AS-304","AS-305","AS-306","AS-307","BQ-001","BQ-010","BQ-011","BQ-012","BQ-013","BQ-014","BQ-015","BQ-016"],
 "B03": ["BQ-017","BQ-018","BQ-019","BQ-020","BQ-021","BQ-022","BQ-023","BQ-024","BQ-025","BZ-016","BZ-019","BZ-020","BZ-021","BZ-022","BZ-023","BZ-024","BZ-025","BZ-026","BZ-027","BZ-028"],
}
def main():
    total = 0
    for bname, ids in BATCHES.items():
        assert len(ids) == 20, bname
        for cid in ids:
            assert cid in P, f"missing {cid}"
            text, basis, conf, trig = P[cid]
            rec = {"case_id": cid, "prediction_text": text, "basis": basis, "confidence": conf, "trigger": trig}
            assert set(rec) == {"case_id","prediction_text","basis","confidence","trigger"}
            assert 0.0 <= conf <= 1.0
            assert set(trig) == {"changed_main","reserve_used","disputed","reason"}
            assert all(isinstance(trig[k], bool) for k in ("changed_main","reserve_used","disputed"))
            with open(f"{OUT}/{cid}.json", "w", encoding="utf-8") as f:
                json.dump(rec, f, ensure_ascii=False, indent=1)
            total += 1
        print(bname, "written", len(ids))
    print("TOTAL", total)
if __name__ == "__main__":
    main()
